,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
' //Get APEX current user ',
'',
'    (function() {',
'      function setUserInfo() {',
'        var userName = ''Current User'';',
'        var userInitials = ''US'';',
'        ',
'        // Try to get from APEX environment',
'        if (typeof apex !== ''undefined'' && apex.env) {',
'          if (apex.env.APP_USER) {',
'            userName = apex.env.APP_USER;',
'            var names = userName.split('' '');',
'            userInitials = (names[0] ? names[0][0].toUpperCase() : '''') + ',
'                          (names[1] ? names[1][0].toUpperCase() : '''');',
'            if (!userInitials) userInitials = ''US'';',
'          }',
'        }',
'        ',
'        var userNameEl = document.getElementById(''userName'');',
'        var userAvatarEl = document.getElementById(''userAvatar'');',
'        ',
'        if (userNameEl) userNameEl.textContent = userName;',
'        if (userAvatarEl) userAvatarEl.textContent = userInitials;',
'      }',
'      ',
'      if (document.readyState === ''loading'') {',
'        document.addEventListener(''DOMContentLoaded'', setUserInfo);',
'      } else {',
'        setUserInfo();',
'      }',
'      ',
'      setTimeout(setUserInfo, 500);',
'    })();',
''))
