'    margin:0 auto;',
'}',
'',
'/* ===== HERO BANNER ===== */',
'',
'.i7-hero{',
'    background:linear-gradient(135deg,#2563eb,#06b6d4);',
'    border-radius:16px;',
'    padding:28px 32px;',
'    color:#fff;',
'    display:flex;',
'    align-items:center;',
'    justify-content:space-between;',
'    margin-bottom:22px;',
'    opacity:0;',
'    transform:translateY(-14px);',
'    animation:i7FadeDown .5s ease forwards;',
'    position:relative;',
'    overflow:hidden;',
'}',
'',
'.i7-hero::after{',
'    content:"";',
'    position:absolute;',
'    top:-40px;',
'    right:-40px;',
'    width:160px;',
'    height:160px;',
'    border-radius:50%;',
'    background:rgba(255,255,255,.08);',
'}',
'',
'.i7-hero-left h1{',
'    font-size:23px;',
'    margin-bottom:6px;',
'}',
'',
'.i7-hero-left p{',
'    font-size:13px;',
'    opacity:.9;',
'}',
'',
'.i7-hero-badge{',
'    background:rgba(255,255,255,.18);',
'    padding:8px 16px;',
'    border-radius:999px;',
'    font-size:12.5px;',
'    font-weight:600;',
'    display:flex;',
'    align-items:center;',
'    gap:8px;',
'}',
'',
'.i7-hero-badge .dot{',
'    width:8px;',
'    height:8px;',
'    border-radius:50%;',
'    background:#22c55e;',
'    animation:i7Pulse 1.6s infinite;',
'}',
'',
'/* ===== STAT CARDS ===== */',
'',
'.i7-stats{',
'    display:grid;',
'    grid-template-columns:repeat(4,1fr);',
'    gap:16px;',
'    margin-bottom:22px;',
'}',
'',
'.i7-stat-card{',
'    background:#fff;',
'    border:1px solid #eef0f3;',
'    border-radius:14px;',
'    padding:18px 20px;',
'    box-shadow:0 4px 14px rgba(0,0,0,.04);',
'    opacity:0;',
'    transform:translateY(16px);',
'    animation:i7FadeUp .5s ease forwards;',
'    transition:.25s;',
'}',
'',
'.i7-stat-card:hover{',
'    transform:translateY(-4px);',
'    box-shadow:0 10px 22px rgba(0,0,0,.08);',
'}',
'',
'.i7-stat-card:nth-child(1){animation-delay:.05s;}',
'.i7-stat-card:nth-child(2){animation-delay:.15s;}',
'.i7-stat-card:nth-child(3){animation-delay:.25s;}',
'.i7-stat-card:nth-child(4){animation-delay:.35s;}',
'',
'.i7-stat-icon{',
'    width:40px;',
'    height:40px;',
'    border-radius:10px;',
'    display:flex;',
'    align-items:center;',
'    justify-content:center;',
'    font-size:19px;',
'    margin-bottom:12px;',
'}',
'',
'.i7-stat-icon.blue{background:#dbeafe;}',
'.i7-stat-icon.green{background:#d1fae5;}',
'.i7-stat-icon.amber{background:#fef3c7;}',
'.i7-stat-icon.red{background:#fee2e2;}',
'',
'.i7-stat-value{',
'    font-size:24px;',
'    font-weight:700;',
'    color:#111827;',
'    margin-bottom:2px;',
'}',
'',
'.i7-stat-label{',
'    font-size:12.5px;',
'    color:#6b7280;',
'}',
'',
'.i7-stat-trend{',
'    font-size:11.5px;',
'    margin-top:8px;',
'    font-weight:600;',
'}',
'',
'.i7-stat-trend.up{color:#059669;}',
'.i7-stat-trend.down{color:#dc2626;}',
'',
'/* ===== MAIN GRID: STATUS + QUICK ACTIONS ===== */',
'',
'.i7-main-grid{',
'    display:grid;',
'    grid-template-columns:1.3fr 1fr;',
'    gap:18px;',
'    margin-bottom:20px;',
'}',
'',
'.i7-panel{',
'    background:#fff;',
'    border:1px solid #eef0f3;',
'    border-radius:14px;',
'    padding:20px;',
'    box-shadow:0 4px 14px rgba(0,0,0,.04);',
'    opacity:0;',
'    transform:translateY(16px);',
'    animation:i7FadeUp .5s ease forwards;',
'    animation-delay:.45s;',
'}',
'',
'.i7-panel h3{',
'    font-size:15px;',
'    color:#111827;',
'    margin-bottom:16px;',
'    display:flex;',
'    align-items:center;',
'    justify-content:space-between;',
'}',
'',
'.i7-live-tag{',
'    font-size:11px;',
'    background:#d1fae5;',
'    color:#059669;',
'    padding:4px 10px;',
'    border-radius:999px;',
'    font-weight:600;',
'    display:flex;',
'    align-items:center;',
'    gap:5px;',
'}',
'',
'.i7-live-tag .dot{',
'    width:6px;',
'    height:6px;',
'    border-radius:50%;',
'    background:#059669;',
'    animation:i7Pulse 1.6s infinite;',
'}',
'',
'.i7-device-row{',
'    display:flex;',
'    align-items:center;',
'    justify-content:space-between;',
'    padding:12px 0;',
'    border-bottom:1px solid #f3f4f6;',
'}',
'',
'.i7-device-row:last-child{',
'    border-bottom:none;',
'}',
'',
'.i7-device-left{',
'    display:flex;',
'    align-items:center;',
'    gap:12px;',
'}',
'',
'.i7-device-icon{',
'    width:36px;',
'    height:36px;',
'    border-radius:9px;',
'    background:#eff6ff;',
'    display:flex;',
'    align-items:center;',
'    justify-content:center;',
'    font-size:16px;',
'}',
'',
'.i7-device-name{',
'    font-size:13.5px;',
'    font-weight:600;',
'    color:#111827;',
'}',
'',
'.i7-device-ip{',
'    font-size:11.5px;',
'    color:#9ca3af;',
'}',
'',
'.i7-badge{',
'    font-size:11px;',
'    font-weight:600;',
'    padding:4px 10px;',
'    border-radius:999px;',
'}',
'',
'.i7-badge.online{background:#d1fae5;color:#059669;}',
'.i7-badge.offline{background:#fee2e2;color:#dc2626;}',
'',
'/* Quick actions panel */',
'',
'.i7-action-btn{',
'    width:100%;',
'    display:flex;',
'    align-items:center;',
'    gap:12px;',
'    padding:12px 14px;',
'    border:1px solid #eef0f3;',
'    border-radius:10px;',
'    background:#fafafa;',
'    margin-bottom:10px;',
'    cursor:pointer;',
'    transition:.2s;',
'    font-size:13.5px;',
'    font-weight:600;',
'    color:#111827;',
'}',
'',
'.i7-action-btn:hover{',
'    background:#eff6ff;',
'    border-color:#bfdbfe;',
'    transform:translateX(4px);',
'}',
'',
'.i7-action-icon{',
'    width:34px;',
'    height:34px;',
'    border-radius:9px;',
'    background:#2563eb;',
'    color:#fff;',
'    display:flex;',
'    align-items:center;',
'    justify-content:center;',
'    font-size:15px;',
'    flex-shrink:0;',
'}',
'',
'/* ===== ANIMATIONS ===== */',
'',
'@keyframes i7FadeDown{',
'    to{opacity:1; transform:translateY(0);}',
'}',
'',
'@keyframes i7FadeUp{',
'    to{opacity:1; transform:translateY(0);}',
'}',
'',
'@keyframes i7Pulse{',
'    0%{box-shadow:0 0 0 0 rgba(34,197,94,.5);}',
'    70%{box-shadow:0 0 0 8px rgba(34,197,94,0);}',
'    100%{box-shadow:0 0 0 0 rgba(34,197,94,0);}',
'}',
'',
'@media(max-width:760px){',
'    .i7-stats{grid-template-columns:repeat(2,1fr);}',
'    .i7-main-grid{grid-template-columns:1fr;}',
'}',
'</style>',
'',
