'<script>',
'(function(){',
'    var counters = document.querySelectorAll(".i7-stat-value[data-count]");',
'',
'    counters.forEach(function(el){',
'        var target = parseInt(el.getAttribute("data-count"), 10);',
'        var current = 0;',
'        var duration = 900;',
'        var stepTime = Math.max(Math.floor(duration / Math.max(target,1)), 25);',
'',
'        if(target === 0){',
'            el.textContent = "0";',
'            return;',
'        }',
'',
'        var timer = setInterval(function(){',
'            current += 1;',
'            el.textContent = current;',
'            if(current >= target){',
'                clearInterval(timer);',
'            }',
'        }, stepTime);',
'    });',
'})();',
'</script>'))
