'<!DOCTYPE html>',
'<html>',
'<head>',
'    <title>InLine 7.0 Dashboard</title>',
'    <style>',
'        /* ============================================',
'           STATIC CONTENT - CSS',
'           ============================================ */',
'        * {',
'            margin: 0;',
'            padding: 0;',
'            box-sizing: border-box;',
'            font-family: ''Segoe UI'', Tahoma, Geneva, Verdana, sans-serif;',
'        }',
'        body {',
'            background: #0b1a2b;',
'            height: 100vh;',
'            overflow: hidden;',
'            display: flex;',
'            justify-content: center;',
'            align-items: center;',
'        }',
'        .dashboard {',
'            background: #ffffff;',
'            width: 98vw;',
'            max-width: 1300px;',
'            height: 94vh;',
'            border-radius: 28px;',
'            box-shadow: 0 25px 70px rgba(0,0,0,0.5);',
'            padding: 28px 36px;',
'            display: flex;',
'            flex-direction: column;',
'            overflow: hidden;',
'        }',
'        .header {',
'            display: flex;',
'            justify-content: space-between;',
'            align-items: center;',
'            border-bottom: 2px solid #e9edf4;',
'            padding-bottom: 16px;',
'            flex-shrink: 0;',
'        }',
'        .header-left {',
'            display: flex;',
'            align-items: center;',
'            gap: 14px;',
'        }',
'        .logo {',
'            font-size: 30px;',
'            font-weight: 800;',
'            color: #0b1f33;',
'            letter-spacing: -0.5px;',
'        }',
'        .logo span {',
'            color: #1a73e8;',
'        }',
'        .badge {',
'            background: #e9f0fe;',
'            padding: 6px 18px;',
'            border-radius: 40px;',
'            font-size: 13px;',
'            font-weight: 600;',
'            color: #1a5aa0;',
'            border: 1px solid #c5d8f0;',
'        }',
'        .status-box {',
'            display: flex;',
'            align-items: center;',
'            gap: 16px;',
'            background: #f6f9fc;',
'            padding: 8px 22px;',
'            border-radius: 40px;',
'            border: 1px solid #dce5ef;',
'        }',
'        .status-dot {',
'            width: 12px;',
'            height: 12px;',
'            border-radius: 50%;',
'            display: inline-block;',
'        }',
'        .status-dot.online { background: #1e8e3e; }',
'        .status-dot.offline { background: #d93025; }',
'        #statusText {',
'            font-weight: 600;',
'            font-size: 14px;',
'            color: #1f334a;',
'        }',
'        .main-grid {',
'            flex: 1;',
'            display: grid;',
'            grid-template-columns: 1.1fr 0.9fr;',
'            gap: 28px;',
'            padding-top: 24px;',
'            min-height: 0;',
'        }',
'        .card {',
'            background: #f8faff;',
'            border-radius: 20px;',
'            padding: 24px 28px;',
'            border: 1px solid #e2eaf3;',
'            display: flex;',
'            flex-direction: column;',
'            overflow: hidden;',
'        }',
'        .card-header {',
'            display: flex;',
'            justify-content: space-between;',
'            align-items: center;',
'            margin-bottom: 12px;',
'        }',
'        .card-title {',
'            font-size: 15px;',
'            font-weight: 700;',
'            text-transform: uppercase;',
'            letter-spacing: 0.5px;',
'            color: #3a5775;',
'        }',
'        .card-title i { margin-right: 8px; }',
'        .stats-row {',
'            display: flex;',
'            align-items: baseline;',
'            gap: 6px;',
'            flex-wrap: wrap;',
'        }',
'        .big-number {',
'            font-size: 62px;',
'            font-weight: 800;',
'            color: #0b1f33;',
'            line-height: 1;',
'        }',
'        .big-number.active {',
'            color: #1a8a44;',
'        }',
'        .stats-label {',
'            font-size: 18px;',
'            font-weight: 500;',
'            color: #3d5a78;',
'            margin-left: 2px;',
'        }',
'        .stats-divider {',
'            margin: 14px 0 12px 0;',
