'];',
'',
'// Store device status',
'var deviceStatusMap = {};',
'var deviceList = [];',
'',
'// Sample data - will be replaced by DB data',
'var inspectionData = [];',
'',
'// =====================================================',
'// FUNCTION DECLARATIONS',
'// =====================================================',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Page Load',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'$(document).ready(function() {',
'    loadDevices();',
'    checkStatus();',
'    loadTableData();',
'    setInterval(checkStatus, 30000);',
'    document.getElementById(''lastUpdate'').innerText = new Date().toLocaleTimeString();',
'});',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Load Table Data from DB/Flask',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function loadTableData() {',
'    // Try Flask API first',
'    fetch(FLASK_URL + ''/api/inspections'')',
'    .then(function(r) { return r.json(); })',
'    .then(function(data) {',
'        if (data.success && data.data) {',
'            inspectionData = data.data;',
'            renderTable();',
