'            loadFromDB();',
'        }',
'    })',
'    .catch(function() {',
'        loadFromDB();',
'    });',
'}',
'',
'function loadFromDB() {',
'    // Oracle APEX AJAX call',
'    if (typeof apex !== ''undefined'' && apex.server) {',
'        apex.server.process(''GET_INSPECTIONS'', {}, {',
'            success: function(data) {',
'                if (data.data) {',
'                    inspectionData = data.data;',
'                    renderTable();',
'                }',
'            }',
'        });',
'    } else {',
'        // Fallback - load sample data if no DB',
'        loadSampleData();',
'    }',
'}',
'',
'// Sample data for demo',
'function loadSampleData() {',
'    inspectionData = [',
'        { INSPECTION_ID: 1, ORDER_NO: ''ORD1001'', CUT: 5, BUNDLE: 12, OPERATOR_CODE: ''OP001'', OPERATION: ''Stitching'', IP_COLOR: ''Green'', DEVICE_IP: ''172.16.17.10'', CREATED_DATE: ''2026-08-06 10:30:00'' },',
'        { INSPECTION_ID: 2, ORDER_NO: ''ORD1002'', CUT: 8, BUNDLE: 15, OPERATOR_CODE: ''OP002'', OPERATION: ''Cutting'', IP_COLOR: ''Red'', DEVICE_IP: ''172.16.17.11'', CREATED_DATE: ''2026-08-06 11:15:00'' },',
'        { INSPECTION_ID: 3, ORDER_NO: ''ORD1003'', CUT: 3, BUNDLE: 8, OPERATOR_CODE: ''OP003'', OPERATION: ''Packing'', IP_COLOR: ''Blue'', DEVICE_IP: ''172.16.17.10'', CREATED_DATE: ''2026-08-06 12:00:00'' }',
'    ];',
'    renderTable();',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Render Table with Device IP Column',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function renderTable() {',
'    var tbody = document.getElementById(''tableBody'');',
'    tbody.innerHTML = '''';',
'    ',
'    if (inspectionData.length === 0) {',
'        tbody.innerHTML = ''<tr><td colspan="9" style="text-align:center; padding:30px; color:#8fa3be;">No records found</td></tr>'';',
'        document.getElementById(''recordCount'').innerText = ''(0 records)'';',
'        return;',
'    }',
'    ',
'    inspectionData.forEach(function(row, index) {',
'        var tr = document.createElement(''tr'');',
'        var deviceIP = row.DEVICE_IP || row.device_ip || ''-'';',
'        tr.innerHTML = `',
'            <td>${row.INSPECTION_ID || index + 1}</td>',
'            <td><strong>${row.ORDER_NO || ''-''}</strong></td>',
'            <td>${row.CUT || ''-''}</td>',
'            <td>${row.BUNDLE || ''-''}</td>',
'            <td>${row.OPERATOR_CODE || ''-''}</td>',
'            <td>${row.OPERATION || ''-''}</td>',
'            <td><span class="status-badge online">${row.IP_COLOR || ''-''}</span></td>',
'            <td><span class="device-ip-badge">${deviceIP}</span></td>',
'            <td style="font-size:11px; color:#5d7b9c;">${row.CREATED_DATE ? new Date(row.CREATED_DATE).toLocaleString() : ''-''}</td>',
'        `;',
'        tbody.appendChild(tr);',
'    });',
'    ',
'    document.getElementById(''recordCount'').innerText = ''('' + inspectionData.length + '' records)'';',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Insert Data with Device IP',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function insertData() {',
'    // Get form values',
'    var orderNo = document.getElementById(''order_no'').value.trim();',
'    var cut = document.getElementById(''cut'').value.trim();',
'    var bundle = document.getElementById(''bundle'').value.trim();',
'    var operatorCode = document.getElementById(''operator_code'').value.trim();',
'    var operation = document.getElementById(''operation'').value;',
'    var ipColor = document.getElementById(''ip_color'').value;',
'    var deviceIP = document.getElementById(''device_ip'').value;',
'    ',
'    // Validation',
'    if (!orderNo) {',
unistr('        showResult(''\274C Order No required!'', ''error'');'),
'        return;',
'    }',
'    if (!cut || isNaN(cut)) {',
unistr('        showResult(''\274C Valid Cut required!'', ''error'');'),
'        return;',
'    }',
'    if (!bundle || isNaN(bundle)) {',
unistr('        showResult(''\274C Valid Bundle required!'', ''error'');'),
'        return;',
'    }',
'    if (!operatorCode) {',
unistr('        showResult(''\274C Operator Code required!'', ''error'');'),
'        return;',
'    }',
'    if (!operation) {',
unistr('        showResult(''\274C Operation required!'', ''error'');'),
'        return;',
'    }',
'    if (!ipColor) {',
unistr('        showResult(''\274C IP Color required!'', ''error'');'),
'        return;',
'    }',
'    if (!deviceIP) {',
unistr('        showResult(''\274C Device IP required!'', ''error'');'),
'        return;',
'    }',
'    ',
unistr('    showResult(''\23F3 Saving...'', ''info'');'),
'    ',
'    // Prepare data',
'    var data = {',
'        ORDER_NO: orderNo,',
'        CUT: parseInt(cut),',
'        BUNDLE: parseInt(bundle),',
'        OPERATOR_CODE: operatorCode,',
'        OPERATION: operation,',
'        IP_COLOR: ipColor,',
'        DEVICE_IP: deviceIP',
'    };',
'    ',
'    // Try Flask API first',
'    fetch(FLASK_URL + ''/api/inspections'', {',
'        method: ''POST'',',
'        headers: { ''Content-Type'': ''application/json'' },',
'        body: JSON.stringify(data)',
'    })',
'    .then(function(r) { return r.json(); })',
'    .then(function(response) {',
'        if (response.success) {',
unistr('            showResult(''\2705 Data inserted successfully!'', ''success'');'),
'            clearForm();',
'            loadTableData();',
'            document.getElementById(''lastUpdate'').innerText = new Date().toLocaleTimeString();',
'        } else {',
'            insertToDB(data);',
'        }',
'    })',
'    .catch(function() {',
'        insertToDB(data);',
'    });',
'}',
'',
'function insertToDB(data) {',
'    if (typeof apex !== ''undefined'' && apex.server) {',
'        apex.server.process(''INSERT_INSPECTION'', {',
'            x01: data.ORDER_NO,',
'            x02: data.CUT,',
'            x03: data.BUNDLE,',
'            x04: data.OPERATOR_CODE,',
'            x05: data.OPERATION,',
'            x06: data.IP_COLOR,',
'            x07: data.DEVICE_IP',
'        }, {',
'            success: function(response) {',
'                if (response.success) {',
unistr('                    showResult(''\2705 Data inserted successfully!'', ''success'');'),
'                    clearForm();',
'                    loadTableData();',
'                    document.getElementById(''lastUpdate'').innerText = new Date().toLocaleTimeString();',
'                } else {',
unistr('                    showResult(''\274C DB Error: '' + (response.error || ''Unknown error''), ''error'');'),
'                }',
'            },',
'            error: function() {',
'                // If DB also fails, add to local array for demo',
unistr('                showResult(''\26A0\FE0F DB not available. Saved locally!'', ''info'');'),
'                var newRow = {',
'                    INSPECTION_ID: inspectionData.length + 1,',
'                    ORDER_NO: data.ORDER_NO,',
'                    CUT: data.CUT,',
'                    BUNDLE: data.BUNDLE,',
'                    OPERATOR_CODE: data.OPERATOR_CODE,',
'                    OPERATION: data.OPERATION,',
'                    IP_COLOR: data.IP_COLOR,',
'                    DEVICE_IP: data.DEVICE_IP,',
'                    CREATED_DATE: new Date().toISOString()',
'                };',
'                inspectionData.push(newRow);',
'                renderTable();',
'                clearForm();',
'                document.getElementById(''lastUpdate'').innerText = new Date().toLocaleTimeString();',
'            }',
'        });',
'    } else {',
'        // No DB - add locally',
unistr('        showResult(''\26A0\FE0F No DB connection. Saved locally!'', ''info'');'),
'        var newRow = {',
'            INSPECTION_ID: inspectionData.length + 1,',
'            ORDER_NO: data.ORDER_NO,',
'            CUT: data.CUT,',
'            BUNDLE: data.BUNDLE,',
'            OPERATOR_CODE: data.OPERATOR_CODE,',
'            OPERATION: data.OPERATION,',
'            IP_COLOR: data.IP_COLOR,',
'            DEVICE_IP: data.DEVICE_IP,',
'            CREATED_DATE: new Date().toISOString()',
'        };',
'        inspectionData.push(newRow);',
'        renderTable();',
'        clearForm();',
'        document.getElementById(''lastUpdate'').innerText = new Date().toLocaleTimeString();',
'    }',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Clear Form',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function clearForm() {',
'    document.getElementById(''order_no'').value = '''';',
'    document.getElementById(''cut'').value = '''';',
'    document.getElementById(''bundle'').value = '''';',
'    document.getElementById(''operator_code'').value = '''';',
'    document.getElementById(''operation'').value = '''';',
'    document.getElementById(''ip_color'').value = '''';',
'    document.getElementById(''device_ip'').value = '''';',
'    document.getElementById(''result_msg'').style.display = ''none'';',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Refresh Table',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function refreshTable() {',
unistr('    showResult(''\D83D\DD04 Refreshing...'', ''info'');'),
'    loadTableData();',
'    setTimeout(function() {',
unistr('        showResult(''\2705 Table refreshed!'', ''success'');'),
'        setTimeout(function() {',
'            document.getElementById(''result_msg'').style.display = ''none'';',
'        }, 2000);',
'    }, 500);',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Result Message',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function showResult(msg, type) {',
'    var el = document.getElementById(''result_msg'');',
'    el.style.display = ''block'';',
'    el.innerHTML = msg;',
'    ',
'    var colors = {',
'        success: { bg: ''#d4edda'', color: ''#155724'', border: ''#c3e6cb'' },',
'        error: { bg: ''#f8d7da'', color: ''#721c24'', border: ''#f5c6cb'' },',
'        info: { bg: ''#d1ecf1'', color: ''#0c5460'', border: ''#bee5eb'' }',
'    };',
'    ',
'    var c = colors[type] || colors.info;',
'    el.style.background = c.bg;',
'    el.style.color = c.color;',
'    el.style.border = ''1px solid '' + c.border;',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Devices Load',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function loadDevices() {',
'    fetch(FLASK_URL + ''/api/devices'')',
'    .then(function(r) { return r.json(); })',
'    .then(function(data) {',
'        if (data.success && data.devices.length > 0) {',
'            populateDevices(data.devices);',
'        } else {',
'            loadDevicesFromDB();',
'        }',
'    })',
'    .catch(function() {',
'        loadDevicesFromDB();',
'    });',
'}',
'',
'function loadDevicesFromDB() {',
'    if (typeof apex !== ''undefined'' && apex.server) {',
'        apex.server.process(''GET_DEVICES'', {}, {',
'            success: function(data) {',
'                if (data.devices) {',
'                    populateDevices(data.devices);',
'                }',
'            }',
'        });',
'    } else {',
'        // Fallback devices',
'        var fallbackDevices = [',
'            { ip: ''172.16.17.10'', name: ''Machine 1'' },',
'            { ip: ''172.16.17.11'', name: ''Machine 2'' }',
'        ];',
'        populateDevices(fallbackDevices);',
'    }',
'}',
'',
'function populateDevices(devices) {',
'    var select = document.getElementById(''device_ip'');',
'    select.innerHTML = ''<option value="">-- choose device --</option>'';',
'    ',
'    deviceList = devices;',
'    deviceStatusMap = {};',
'    ',
'    devices.forEach(function(d) {',
'        var ip = d.ip || d.device_ip || d.address;',
'        var name = d.name || d.device_name || ''LED'';',
'        var status = d.status || ''online'';',
'        ',
'        deviceStatusMap[ip] = status;',
'        ',
'        var opt = document.createElement(''option'');',
'        opt.value = ip;',
'        opt.text = ip + '' - '' + name;',
'        select.appendChild(opt);',
'    });',
'    ',
'    updateOfficeLine();',
'}',
'',
'function updateOfficeLine() {',
'    MACHINES.forEach(function(machine) {',
'        var dot = document.getElementById(machine.id + ''Dot'');',
'        var status = deviceStatusMap[machine.ip];',
'        var isOnline = (status === ''online'' || status === ''active'' || status === true);',
'        dot.className = ''dot '' + (isOnline ? ''on'' : ''off'');',
'    });',
'}',
'',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'// Status Check',
unistr('// \2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500\2500'),
'function checkStatus() {',
'    fetch(FLASK_URL + ''/api/status'')',
'    .then(function(r) { return r.json(); })',
'    .then(function(data) {',
'        var dot = document.getElementById(''statusDot'');',
'        var text = document.getElementById(''statusText'');',
'        if (data.mqtt === ''connected'') {',
'            dot.className = ''status-dot online'';',
unistr('            text.innerText = ''\D83D\DFE2 Bridge Online \00B7 '' + (data.total_devices || 0) + '' devices'';'),
'        } else {',
'            dot.className = ''status-dot offline'';',
unistr('            text.innerText = ''\D83D\DD34 MQTT Disconnected'';'),
'        }',
'    })',
'    .catch(function() {',
'        document.getElementById(''statusDot'').className = ''status-dot offline'';',
unistr('        document.getElementById(''statusText'').innerText = ''\D83D\DD34 Flask Offline'';'),
'    });',
'} -->'))
