,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="inline7Loader"></div>',
'',
'<script>',
'(function () {',
'',
'    var htmlUrl =',
'        // "#APP_FILES#InLine_7_0_Static_HTML_CSS.html";',
'        "#APP_FILES#INLINE_INSPECTION_MODERN1.html";',
'    var jsUrl = "#APP_FILES#InLine_7_0_Static_JS.min1.js";',
'',
'    fetch(htmlUrl)',
'        .then(function (response) {',
'',
'            if (!response.ok) {',
'                throw new Error(',
'                    "HTML file not found: " +',
'                    response.status',
'                );',
'            }',
'',
'            return response.text();',
'',
'        })',
'        .then(function (html) {',
'',
'            document',
'                .getElementById("inline7Loader")',
'                .innerHTML = html;',
'',
'            var script =',
'                document.createElement("script");',
'',
'            script.src = jsUrl;',
'',
'            script.onload = function () {',
'                console.log(',
'                    "InLine 7.0 JS loaded successfully"',
'                );',
'            };',
'',
'            script.onerror = function () {',
'                console.error(',
'                    "InLine 7.0 JS failed to load"',
'                );',
'            };',
'',
'            document.body.appendChild(script);',
'',
'        })',
'        .catch(function (error) {',
'',
'            console.error(error);',
'',
'            document.getElementById(',
'                "inline7Loader"',
'            ).innerHTML =',
'                "<div style=''padding:30px;color:red''>" +',
'                "Unable to load InLine application." +',
'                "</div>";',
'',
'        });',
'',
'})();',
'</script>'))
