,p_process_name=>'DELETE_INSPECTION'
,p_static_id=>'delete-inspection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    DELETE FROM INLINE_INSPECTION',
'    WHERE INSPECTION_ID = APEX_APPLICATION.G_X01;',
'',
'    HTP.P(''{"status":"success","message":"Record deleted successfully"}'');',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        ROLLBACK;',
'',
'        HTP.P(',
'            ''{"status":"error","message":"'' ||',
'            REPLACE(SQLERRM, ''"'', ''\"'') ||',
'            ''"}''',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
