wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6458843777263019)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_DEVICES'
,p_static_id=>'get-devices'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'BEGIN',
'    apex_json.open_object;',
'    apex_json.open_array(''devices'');',
'',
'    FOR r IN (',
'        SELECT ip_address AS ip,',
'               NVL(device_name, ''LED Device'') AS name,',
'               NVL(current_color, ''off'') AS current_color,',
'               NVL(status, ''offline'') AS status',
'        FROM led_devices',
'        ORDER BY ip_address',
'    ) LOOP',
'        apex_json.open_object;',
'        apex_json.write(''ip'', r.ip);',
'        apex_json.write(''name'', r.name);',
'        apex_json.write(''current_color'', r.current_color);',
'        apex_json.write(''status'', r.status);',
'        apex_json.close_object;',
'    END LOOP;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'END;',
'',
'',
'',
'',
'-- DECLARE',
'--     v_devices APEX_JSON.t_values;',
'-- BEGIN',
'--     APEX_JSON.open_object;',
'--     APEX_JSON.open_array(''devices'');',
'',
'--     FOR r IN (',
'--         SELECT ip_address, device_name, current_color',
