wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11434762495338110)
,p_process_sequence=>50
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_INSPECTION_REPORT'
,p_static_id=>'get-inspection-report'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'BEGIN',
'    apex_json.open_object;',
'    apex_json.open_array(''data'');',
'',
'    FOR r IN (',
'        SELECT INSPECTION_ID, ORDER_NO, CUT, BUNDLE,',
'               OPERATOR_CODE, OPERATION, IP_COLOR,',
'               CREATED_DATE, DEVICE_IP',
'        FROM INLINE_INSPECTION',
'        ORDER BY CREATED_DATE DESC, INSPECTION_ID DESC',
'    ) LOOP',
'        apex_json.open_object;',
'        apex_json.write(''INSPECTION_ID'', r.INSPECTION_ID);',
'        apex_json.write(''ORDER_NO'', r.ORDER_NO);',
'        apex_json.write(''CUT'', r.CUT);',
'        apex_json.write(''BUNDLE'', r.BUNDLE);',
'        apex_json.write(''OPERATOR_CODE'', r.OPERATOR_CODE);',
'        apex_json.write(''OPERATION'', r.OPERATION);',
'        apex_json.write(''IP_COLOR'', r.IP_COLOR);',
'        apex_json.write(''CREATED_DATE'', TO_CHAR(r.CREATED_DATE,''DD-MON-YYYY HH24:MI:SS''));',
'        apex_json.write(''DEVICE_IP'', r.DEVICE_IP);',
'        apex_json.close_object;',
'    END LOOP;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11434762495338110
