,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_INSPECTIONS'
,p_static_id=>'get-inspections'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_cursor SYS_REFCURSOR;',
'BEGIN',
'    OPEN v_cursor FOR',
'        SELECT ',
'            INSPECTION_ID,',
'            ORDER_NO,',
'            CUT,',
'            BUNDLE,',
'            OPERATOR_CODE,',
'            OPERATION,',
'            IP_COLOR,',
'            DEVICE_IP,',
'            TO_CHAR(CREATED_DATE, ''YYYY-MM-DD HH24:MI:SS'') AS CREATED_DATE',
'        FROM INLINE_INSPECTION',
'        ORDER BY CREATED_DATE DESC;',
'    ',
'    apex_json.open_object;',
'    apex_json.write(''success'', true);',
'    apex_json.write(''data'', v_cursor);',
'    apex_json.close_object;',
'    ',
'EXCEPTION WHEN OTHERS THEN',
'    IF v_cursor%ISOPEN THEN',
'        CLOSE v_cursor;',
'    END IF;',
'    apex_json.open_object;',
'    apex_json.write(''success'', false);',
'    apex_json.write(''error'', SQLERRM);',
'    apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6459336664263024
,p_created_on=>wwv_flow_imp.dz('20260807184424Z')
,p_updated_on=>wwv_flow_imp.dz('20260807190353Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11434890473338111)
,p_process_sequence=>60
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_OPERATORS'
,p_static_id=>'get-operators'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.OPEN_ARRAY(''data'');',
'',
'    FOR r IN (',
'        SELECT EMPNO || ''-'' || ENAME AS OPERATOR',
'        FROM EMP',
'        ORDER BY EMPNO',
'    )',
'    LOOP',
'',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(',
'            ''operator'',',
'            r.OPERATOR',
'        );',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'',
'    END LOOP;',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'    APEX_JSON.CLOSE_OBJECT;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11434890473338111
,p_created_on=>wwv_flow_imp.dz('20260812162657Z')
,p_updated_on=>wwv_flow_imp.dz('20260812162657Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6459203275263023)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_INSPECTION'
,p_static_id=>'insert-inspection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_id NUMBER;',
'BEGIN',
'    INSERT INTO INLINE_INSPECTION',
'    (',
'        ORDER_NO, CUT, BUNDLE, OPERATOR_CODE,',
'        OPERATION, IP_COLOR, CREATED_DATE, DEVICE_IP',
'    )',
'    VALUES',
'    (',
'        apex_application.g_x01,',
'        TO_NUMBER(apex_application.g_x02),',
'        TO_NUMBER(apex_application.g_x03),',
'        apex_application.g_x04,',
'        apex_application.g_x05,',
'        apex_application.g_x06,',
'        SYSDATE,',
'        apex_application.g_x07',
'    )',
'    RETURNING INSPECTION_ID INTO l_id;',
'',
'    COMMIT;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', TRUE);',
'    apex_json.write(''inspection_id'', l_id);',
'    apex_json.write(''message'', ''Inspection data inserted successfully'');',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        apex_json.open_object;',
'        apex_json.write(''success'', FALSE);',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6459203275263023
,p_created_on=>wwv_flow_imp.dz('20260807184410Z')
,p_updated_on=>wwv_flow_imp.dz('20260812115809Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6459076852263021)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UPDATE_LED_COLOR'
,p_static_id=>'update-led-color'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_ip    VARCHAR2(20) := APEX_APPLICATION.G_X01;',
'    v_color VARCHAR2(20) := APEX_APPLICATION.G_X02;',
'    v_old   VARCHAR2(20);',
'BEGIN',
'    SELECT current_color',
'    INTO   v_old',
'    FROM   led_devices',
'    WHERE  ip_address = v_ip;',
'',
'    UPDATE led_devices',
'    SET    current_color = v_color,',
'           last_seen     = SYSTIMESTAMP,',
'           status        = ''online''',
'    WHERE  ip_address = v_ip;',
'',
'    INSERT INTO led_color_log (',
'        ip_address, old_color,',
'        new_color,  changed_by',
'    ) VALUES (',
'        v_ip,   v_old,',
'        v_color, NVL(APEX_APPLICATION.G_USER, ''SYSTEM'')',
'    );',
'',
'    COMMIT;',
'',
'    APEX_JSON.open_object;',
'    APEX_JSON.write(''status'', ''success'');',
'    APEX_JSON.close_object;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        APEX_JSON.open_object;',
'        APEX_JSON.write(''status'', ''error'');',
'        APEX_JSON.write(''message'', SQLERRM);',
'        APEX_JSON.close_object;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6459076852263021
,p_created_on=>wwv_flow_imp.dz('20260806142946Z')
,p_updated_on=>wwv_flow_imp.dz('20260806142946Z')
,p_created_by=>'AMIR'
,p_updated_by=>'AMIR'
);
end;
