,p_template=>4073835273271169698
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    d.device_name       AS "Device Name",',
'    d.ip_address        AS "IP Address",',
'    d.location          AS "Location",',
'',
'    CASE d.current_color',
'        WHEN ''red''',
unistr('        THEN ''<span style="background:#dc3545;color:white;padding:3px 10px;border-radius:10px;">\D83D\DD34 RED</span>'''),
'        WHEN ''green''',
unistr('        THEN ''<span style="background:#28a745;color:white;padding:3px 10px;border-radius:10px;">\D83D\DFE2 GREEN</span>'''),
'        WHEN ''blue''',
unistr('        THEN ''<span style="background:#007bff;color:white;padding:3px 10px;border-radius:10px;">\D83D\DD35 BLUE</span>'''),
'        WHEN ''yellow''',
unistr('        THEN ''<span style="background:#ffc107;color:black;padding:3px 10px;border-radius:10px;">\D83D\DFE1 YELLOW</span>'''),
'        WHEN ''white''',
unistr('        THEN ''<span style="background:#f8f9fa;color:black;padding:3px 10px;border-radius:10px;border:1px solid #ddd;">\26AA WHITE</span>'''),
'        ELSE',
unistr('        ''<span style="background:#343a40;color:white;padding:3px 10px;border-radius:10px;">\26AB OFF</span>'''),
'    END AS "Current Color",',
'',
'    CASE d.status',
'        WHEN ''online''',
unistr('        THEN ''<span style="color:green;font-weight:bold;">\D83D\DFE2 Online</span>'''),
'        ELSE',
unistr('        ''<span style="color:red;font-weight:bold;">\D83D\DD34 Offline</span>'''),
'    END AS "Status",',
'',
'    TO_CHAR(d.last_seen, ''DD-Mon-YYYY HH24:MI:SS'') AS "Last Seen"',
'',
'FROM led_devices d',
'ORDER BY d.device_name',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
