,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_DEVICES'
,p_static_id=>'get-devices'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'DECLARE',
'    v_devices APEX_JSON.t_values;',
'BEGIN',
'    APEX_JSON.open_object;',
'    APEX_JSON.open_array(''devices'');',
'',
'    FOR r IN (',
'        SELECT ip_address, device_name, current_color',
'        FROM   led_devices',
'        ORDER BY device_name',
'    ) LOOP',
'        APEX_JSON.open_object;',
'        APEX_JSON.write(''ip'',    r.ip_address);',
'        APEX_JSON.write(''name'',  r.device_name);',
'        APEX_JSON.write(''color'', r.current_color);',
'        APEX_JSON.close_object;',
'    END LOOP;',
'',
'    APEX_JSON.close_array;',
'    APEX_JSON.close_object;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8881715101911323
