'        }',
'',
'        .footer {',
'            flex-shrink: 0;',
'            text-align: right;',
'            font-size: 10.5px;',
'            color: #8fa3be;',
'            border-top: 1px solid #e5ecf5;',
'            padding-top: 8px;',
'            margin-top: 6px;',
'        }',
'',
'        ::-webkit-scrollbar { width: 6px; }',
'        ::-webkit-scrollbar-track { background: #f1f1f1; border-radius: 10px; }',
'        ::-webkit-scrollbar-thumb { background: #c1d0e0; border-radius: 10px; }',
'        ::-webkit-scrollbar-thumb:hover { background: #a0b5cc; }',
'',
'        /* responsive */',
'        @media (max-width: 820px) {',
'            .dashboard { padding: 12px 14px; height: 98vh; }',
'            .main-grid { grid-template-columns: 1fr; gap: 14px; }',
'            .office-line .machines { gap: 10px; flex-wrap: wrap; }',
'        }',
'        @media (max-width: 480px) {',
'            .header { flex-wrap: wrap; gap: 6px; }',
'            .status-box { padding: 4px 12px; }',
'            .form-row { grid-template-columns: 1fr; }',
'        }',
'    </style>',
'</head>',
'<body>',
'    <div class="dashboard">',
'        <!-- HEADER -->',
'        <div class="header">',
'            <div class="header-left">',
unistr('                <div class="logo">\26A1 InLine <span>7.0</span></div>'),
'                <span class="badge">Data Entry</span>',
'            </div>',
'            <div class="status-box">',
'                <span class="status-dot online" id="statusDot"></span>',
unistr('                <span id="statusText">\D83D\DFE2 Bridge Online</span>'),
'            </div>',
'        </div>',
'',
'        <!-- OFFICE LINE -->',
'        <div class="office-line">',
unistr('            <span class="label">\D83C\DFE2 Office Line</span>'),
'            <div class="machines" id="officeMachines">',
'                <div class="machine-status" id="machine1">',
'                    <span class="dot on" id="machine1Dot"></span>',
'                    <span class="name" id="machine1Name">Machine 1</span>',
'                    <span class="ip" id="machine1IP">(172.16.17.10)</span>',
'                </div>',
'                <div class="machine-status" id="machine2">',
'                    <span class="dot on" id="machine2Dot"></span>',
'                    <span class="name" id="machine2Name">Machine 2</span>',
'                    <span class="ip" id="machine2IP">(172.16.17.11)</span>',
'                </div>',
'            </div>',
'        </div>',
'',
'        <!-- MAIN GRID -->',
'        <div class="main-grid">',
'            <!-- LEFT: DATA ENTRY FORM -->',
'            <div class="form-card">',
unistr('                <h3>\D83D\DCDD Data Entry Form</h3>'),
'',
'                <div class="form-row">',
'                    <div class="form-group">',
'                        <label for="order_no">Order No</label>',
'                        <input type="text" id="order_no" placeholder="e.g., ORD1001">',
'                    </div>',
'                    <div class="form-group">',
'                        <label for="cut">Cut</label>',
'                        <input type="number" id="cut" placeholder="e.g., 5">',
'                    </div>',
'                </div>',
'',
'                <div class="form-row">',
'                    <div class="form-group">',
'                        <label for="bundle">Bundle</label>',
'                        <input type="number" id="bundle" placeholder="e.g., 12">',
'                    </div>',
'                    <div class="form-group">',
'                        <label for="operator_code">Operator Code</label>',
'                        <input type="text" id="operator_code" placeholder="e.g., OP001">',
'                    </div>',
'                </div>',
'',
'                <div class="form-row">',
'                    <div class="form-group">',
'                        <label for="operation">Operation</label>',
'                        <select id="operation">',
'                            <option value="">Select Operation</option>',
'                            <option value="Stitching">Stitching</option>',
'                            <option value="Cutting">Cutting</option>',
'                            <option value="Packing">Packing</option>',
'                            <option value="Quality Check">Quality Check</option>',
'                            <option value="Assembly">Assembly</option>',
'                        </select>',
'                    </div>',
'                    <div class="form-group">',
'                        <label for="ip_color">IP Color</label>',
'                        <select id="ip_color">',
'                            <option value="">Select Color</option>',
unistr('                            <option value="Red">\D83D\DD34 Red</option>'),
unistr('                            <option value="Green">\D83D\DFE2 Green</option>'),
unistr('                            <option value="Blue">\D83D\DD35 Blue</option>'),
unistr('                            <option value="Yellow">\D83D\DFE1 Yellow</option>'),
unistr('                            <option value="White">\26AA White</option>'),
'                        </select>',
'                    </div>',
'                </div>',
'',
'                <div class="form-row">',
'                    <div class="form-group" style="grid-column: 1 / -1;">',
'                        <label for="device_ip">Select Device IP</label>',
'                        <select id="device_ip">',
'                            <option value="">-- choose device --</option>',
'                            <option value="172.16.17.10">Machine 1 (172.16.17.10)</option>',
'                            <option value="172.16.17.11">Machine 2 (172.16.17.11)</option>',
'                        </select>',
'                    </div>',
'                </div>',
'',
'                <div class="form-actions">',
unistr('                    <button class="btn-primary" onclick="insertData()">\D83D\DCBE Insert Data</button>'),
unistr('                    <button class="btn-secondary" onclick="clearForm()">\D83D\DDD1\FE0F Clear</button>'),
'                </div>',
'                <div id="result_msg"></div>',
'            </div>',
'',
'            <!-- RIGHT: TABLE -->',
'            <div class="table-card">',
'                <div class="header-actions">',
unistr('                    <h3>\D83D\DCCB Inspection Data <small id="recordCount">(0 records)</small></h3>'),
unistr('                    <button class="btn-secondary" onclick="refreshTable()" style="padding:6px 16px; font-size:12px; flex:0;">\D83D\DD04 Refresh</button>'),
'                </div>',
'                <div class="table-wrapper">',
'                    <table id="dataTable">',
'                        <thead>',
'                            <tr>',
'                                <th>ID</th>',
'                                <th>Order No</th>',
'                                <th>Cut</th>',
'                                <th>Bundle</th>',
'                                <th>Operator</th>',
'                                <th>Operation</th>',
'                                <th>Color</th>',
'                                <th>Device IP</th>',
'                                <th>Created</th>',
'                            </tr>',
'                        </thead>',
'                        <tbody id="tableBody">',
'                            <!-- data rows injected -->',
'                        </tbody>',
'                    </table>',
'                </div>',
'            </div>',
'        </div>',
'',
'        <div class="footer">',
unistr('            InLine 7.0 \00B7 Real-time Dashboard \00B7 <span id="lastUpdate">-</span>'),
'        </div>',
'    </div>',
'',
'    <script>',
'        (function() {',
'            // ---------- sample data ----------',
'            let inspectionData = [',
'                { id: 1, order_no: ''ORD1001'', cut: 5, bundle: 12, operator: ''OP001'', operation: ''Stitching'', color: ''Red'', device_ip: ''172.16.17.10'', created: ''2026-08-10 09:23'' },',
'                { id: 2, order_no: ''ORD1002'', cut: 3, bundle: 8, operator: ''OP004'', operation: ''Cutting'', color: ''Blue'', device_ip: ''172.16.17.11'', created: ''2026-08-10 10:05'' },',
'                { id: 3, order_no: ''ORD1003'', cut: 7, bundle: 5, operator: ''OP002'', operation: ''Packing'', color: ''Green'', device_ip: ''172.16.17.10'', created: ''2026-08-10 11:12'' }',
'            ];',
'            let nextId = 4;',
'',
'            // DOM refs',
'            const tbody = document.getElementById(''tableBody'');',
'            const recordCount = document.getElementById(''recordCount'');',
'            const lastUpdate = document.getElementById(''lastUpdate'');',
'            const resultMsg = document.getElementById(''result_msg'');',
'',
'            // form fields',
'            const orderNo = document.getElementById(''order_no'');',
'            const cut = document.getElementById(''cut'');',
'            const bundle = document.getElementById(''bundle'');',
'            const operatorCode = document.getElementById(''operator_code'');',
'            const operation = document.getElementById(''operation'');',
'            const ipColor = document.getElementById(''ip_color'');',
'            const deviceIp = document.getElementById(''device_ip'');',
'',
'            // ---------- helpers ----------',
'            function formatDate() {',
'                const d = new Date();',
'                return d.getFullYear() + ''-'' + ',
'                       String(d.getMonth()+1).padStart(2,''0'') + ''-'' + ',
'                       String(d.getDate()).padStart(2,''0'') + '' '' + ',
'                       String(d.getHours()).padStart(2,''0'') + '':'' + ',
'                       String(d.getMinutes()).padStart(2,''0'');',
'            }',
'',
'            function renderTable() {',
'                if (!tbody) return;',
'                tbody.innerHTML = '''';',
'                if (inspectionData.length === 0) {',
'                    const row = document.createElement(''tr'');',
'                    const td = document.createElement(''td'');',
'                    td.colSpan = 9;',
'                    td.textContent = ''No records found.'';',
'                    td.style.textAlign = ''center'';',
'                    td.style.padding = ''24px'';',
'                    td.style.color = ''#6c859e'';',
'                    row.appendChild(td);',
'                    tbody.appendChild(row);',
'                } else {',
'                    inspectionData.forEach(item => {',
'                        const tr = document.createElement(''tr'');',
'                        const fields = [''id'',''order_no'',''cut'',''bundle'',''operator'',''operation'',''color'',''device_ip'',''created''];',
'                        fields.forEach(key => {',
'                            const td = document.createElement(''td'');',
'                            if (key === ''device_ip'') {',
'                                const span = document.createElement(''span'');',
'                                span.className = ''device-ip-badge'';',
'                                span.textContent = item[key] || ''-'';',
'                                td.appendChild(span);',
'                            } else {',
'                                td.textContent = item[key] !== undefined && item[key] !== null ? item[key] : ''-'';',
'                            }',
'                            tr.appendChild(td);',
'                        });',
'                        tbody.appendChild(tr);',
'                    });',
'                }',
'                recordCount.textContent = `(${inspectionData.length} records)`;',
'                lastUpdate.textContent = ''Last updated: '' + formatDate();',
'            }',
'',
'            function showMessage(text, type) {',
'                resultMsg.textContent = text;',
'                resultMsg.className = type;',
'                setTimeout(() => {',
'                    resultMsg.className = '''';',
'                    resultMsg.style.display = ''none'';',
'                }, 3500);',
'            }',
'',
'            // ---------- actions ----------',
'            window.insertData = function() {',
'                // validation',
'                const order = orderNo.value.trim();',
'                const cutVal = cut.value.trim();',
'                const bundleVal = bundle.value.trim();',
'                const opCode = operatorCode.value.trim();',
'                const opSel = operation.value;',
'                const colorSel = ipColor.value;',
'                const deviceSel = deviceIp.value;',
'',
'                if (!order) { showMessage(''Order No is required.'', ''error''); return; }',
'                if (!cutVal || isNaN(cutVal) || parseInt(cutVal) <= 0) { showMessage(''Cut must be a positive number.'', ''error''); return; }',
'                if (!bundleVal || isNaN(bundleVal) || parseInt(bundleVal) <= 0) { showMessage(''Bundle must be a positive number.'', ''error''); return; }',
'                if (!opCode) { showMessage(''Operator Code is required.'', ''error''); return; }',
'                if (!opSel) { showMessage(''Please select an Operation.'', ''error''); return; }',
'                if (!colorSel) { showMessage(''Please select an IP Color.'', ''error''); return; }',
'                if (!deviceSel) { showMessage(''Please select a Device IP.'', ''error''); return; }',
'',
'                const newRecord = {',
'                    id: nextId++,',
'                    order_no: order,',
'                    cut: parseInt(cutVal),',
'                    bundle: parseInt(bundleVal),',
'                    operator: opCode,',
'                    operation: opSel,',
'                    color: colorSel,',
'                    device_ip: deviceSel,',
'                    created: formatDate()',
'                };',
'',
'                inspectionData.push(newRecord);',
'                renderTable();',
'                clearForm();',
unistr('                showMessage(''\2705 Data inserted successfully!'', ''success'');'),
'            };',
'',
'            window.clearForm = function() {',
'                orderNo.value = '''';',
'                cut.value = '''';',
'                bundle.value = '''';',
'                operatorCode.value = '''';',
'                operation.value = '''';',
'                ipColor.value = '''';',
'                deviceIp.value = '''';',
'                resultMsg.className = '''';',
